def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return value

    def normalize_phone(value):
        value = value or ""
        marker = re.search(r"ext|x|#", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = (value or "").strip()

        zip_plus_four = re.fullmatch(r"(\d{4,5})-\d{4}", value)
        if zip_plus_four:
            value = zip_plus_four.group(1)

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError("Invalid updated value: {!r}".format(value))

    def is_opted_out(value):
        return (value or "").strip().lower() in {"y", "yes", "true", "1"}

    normalized = []

    for input_index, row in enumerate(rows):
        item = {
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": normalize_email(row["email"]),
            "phone": normalize_phone(row["phone"]),
            "zip": normalize_zip(row["zip"]),
            "source": (row["source"] or "").strip().lower(),
            "updated_dt": parse_updated(row["updated"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"] or "")
                if tag.strip()
            },
            "input_index": input_index,
        }

        # Rows without either valid contact method cannot participate in matching.
        if item["email"] or item["phone"]:
            normalized.append(item)

    # Disjoint-set structure for transitive matching.
    parent = list(range(len(normalized)))
    size = [1] * len(normalized)

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return

        if size[left_root] < size[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        size[left_root] += size[right_root]

    email_owner = {}
    phone_last_owner = {}

    for index, item in enumerate(normalized):
        if item["email"]:
            previous = email_owner.get(item["email"])
            if previous is None:
                email_owner[item["email"]] = index
            else:
                union(index, previous)

        if item["phone"] and item["last_name"]:
            key = (item["phone"], item["last_name"].casefold())
            previous = phone_last_owner.get(key)
            if previous is None:
                phone_last_owner[key] = index
            else:
                union(index, previous)

    groups = {}
    for index, item in enumerate(normalized):
        groups.setdefault(find(index), []).append(item)

    def choose_field(group, field):
        candidates = [item for item in group if item[field]]
        if not candidates:
            return ""

        best = max(
            candidates,
            key=lambda item: (
                item["source"] == "manual",
                item["updated_dt"],
                -item["input_index"],
            ),
        )
        return best[field]

    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(item["input_index"] for item in group),
    )

    result = []
    for group in ordered_groups:
        all_tags = set()
        for item in group:
            all_tags.update(item["tags"])

        latest_updated = max(item["updated_dt"] for item in group)

        result.append({
            "first_name": choose_field(group, "first_name"),
            "last_name": choose_field(group, "last_name"),
            "zip": choose_field(group, "zip"),
            "email": choose_field(group, "email"),
            "phone": choose_field(group, "phone"),
            "source": choose_field(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": (
                "Y" if any(item["opted_out"] for item in group) else "N"
            ),
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return result
